package com.backend.googlecalendar;

import com.backend.googlecalendar.GoogleCalendarData.Connection;
import com.backend.googlecalendar.GoogleCalendarData.EventSync;

import com.backend.barbers.*;
import com.backend.scheduling.*;
import com.backend.customers.*;
import com.backend.units.*;
import com.backend.whatsapp.WhatsAppCrypto;
import jakarta.persistence.*;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.http.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.client.RestClient;
import org.springframework.web.server.ResponseStatusException;
import org.springframework.web.servlet.view.RedirectView;
import java.time.*;
import java.util.*;

@Service @Transactional
public class GoogleCalendarService {
    public record Owner(String type,UUID id,UUID tenantId){}
    private final EntityManager em; private final BarberRepository barbers; private final AppointmentRepository appointments; private final CustomerRepository customers; private final UnitRepository units; private final GoogleCalendarCrypto crypto;
    private final RestClient http=RestClient.create(); private final String clientId,secret,callback,frontend;
    public GoogleCalendarService(EntityManager em,BarberRepository barbers,AppointmentRepository appointments,CustomerRepository customers,UnitRepository units,GoogleCalendarCrypto crypto,
      @Value("${google.calendar.client-id:}") String clientId,@Value("${google.calendar.client-secret:}") String secret,@Value("${google.calendar.callback-url:}") String callback,@Value("${app.frontend-url:http://localhost:3000}") String frontend){
        this.em=em;this.barbers=barbers;this.appointments=appointments;this.customers=customers;this.units=units;this.crypto=crypto;this.clientId=clientId;this.secret=secret;this.callback=callback;this.frontend=frontend.replaceAll("/$","");
    }
    public Owner barberOwner(UUID tenant,UUID user){BarberProfile b=barbers.findByUser_Id(user).filter(x->tenant.equals(x.getUnit().getTenant().getId())).orElseThrow(()->new ResponseStatusException(HttpStatus.FORBIDDEN,"Perfil de barbeiro não encontrado"));return new Owner("BARBER",b.getId(),tenant);}
    private Connection find(Owner o){return em.createQuery("select c from GcConnection c where c.ownerType=:t and c.ownerId=:id",Connection.class).setParameter("t",o.type()).setParameter("id",o.id()).getResultStream().findFirst().orElse(null);}
    private Connection obtain(Owner o){Connection c=find(o);if(c==null){c=new Connection();c.ownerType=o.type();c.ownerId=o.id();c.tenantId=o.tenantId();em.persist(c);}return c;}
    public record Status(String scope,boolean configured,boolean connected,String status,String calendarId,String calendarSummary,String googleEmail,Instant lastSyncAt,long pendingCount,long failedCount,String lastError){}
    public Status status(Owner o){Connection c=find(o);if(c==null)return new Status(o.type(),ready(),false,"DISCONNECTED",null,null,null,null,0,0,null);return view(o,c);}
    private Status view(Owner o,Connection c){long pending=count(o,"QUEUED","PROCESSING");long failed=count(o,"FAILED");return new Status(o.type(),ready(),c.enabled&&c.accessEncrypted!=null,c.status,c.calendarId,c.calendarSummary,c.googleEmail,c.lastSyncAt,pending,failed,c.lastError);}
    private long count(Owner o,String... states){if(states.length==0)return 0;return em.createQuery("select count(s) from GcEventSync s where s.connectionId=:id and s.status in :st",Long.class).setParameter("id",Optional.ofNullable(find(o)).map(c->c.id).orElse(new UUID(0,0))).setParameter("st",List.of(states)).getSingleResult();}
    private boolean ready(){return crypto.ready()&&!clientId.isBlank()&&!secret.isBlank()&&!callback.isBlank();}
    public Map<String,String> connect(Owner o,String returnTo){need(ready(),"Google Calendar ainda não está configurado pelo operador do LineUp");String path=returnTo==null?"/admin/configuracoes/integracoes/google-calendar":returnTo;need(Set.of("/admin/configuracoes/integracoes/google-calendar","/barbeiro/configuracoes/integracoes/google-calendar","/barbeiro/configuracoes").contains(path),"Destino inválido");Connection c=obtain(o);String state=UUID.randomUUID()+"."+UUID.randomUUID();c.stateHash=WhatsAppCrypto.hash(state);c.stateExpiresAt=Instant.now().plusSeconds(600);c.returnTo=path;c.initiatedBy=UUID.randomUUID();
        String url="https://accounts.google.com/o/oauth2/v2/auth?client_id="+enc(clientId)+"&redirect_uri="+enc(callback)+"&response_type=code&scope="+enc("https://www.googleapis.com/auth/calendar.events https://www.googleapis.com/auth/calendar.calendarlist.readonly https://www.googleapis.com/auth/userinfo.email")+"&access_type=offline&prompt=consent&state="+enc(state);return Map.of("authorizationUrl",url);}
    public RedirectView callback(String code,String state,String error){Connection c=null;for(Connection x:em.createQuery("select c from GcConnection c where c.stateExpiresAt>:now",Connection.class).setParameter("now",Instant.now()).getResultList())if(x.stateHash!=null&&state!=null&&x.stateHash.equals(WhatsAppCrypto.hash(state))){c=x;break;}if(c==null)return redirect("/admin/configuracoes/integracoes/google-calendar","error");String dest=c.returnTo==null?"/admin/configuracoes/integracoes/google-calendar":c.returnTo;c.stateHash=null;c.stateExpiresAt=null;c.returnTo=null;if(error!=null||code==null){c.status="ERROR";c.lastError="Autorização cancelada";return redirect(dest,"error");}
        try{Map token=http.post().uri("https://oauth2.googleapis.com/token").contentType(MediaType.APPLICATION_FORM_URLENCODED).body("code="+enc(code)+"&client_id="+enc(clientId)+"&client_secret="+enc(secret)+"&redirect_uri="+enc(callback)+"&grant_type=authorization_code").retrieve().body(Map.class);c.accessEncrypted=crypto.encrypt(c.tenantId,(String)token.get("access_token"));if(token.get("refresh_token")!=null)c.refreshEncrypted=crypto.encrypt(c.tenantId,(String)token.get("refresh_token"));c.accessExpiresAt=Instant.now().plusSeconds(((Number)token.getOrDefault("expires_in",3600)).longValue());Map profile=http.get().uri("https://www.googleapis.com/oauth2/v2/userinfo").header("Authorization","Bearer "+token.get("access_token")).retrieve().body(Map.class);c.googleEmail=(String)profile.get("email");c.enabled=true;c.status="CONNECTED";c.lastError=null;return redirect(dest,"connected");}
        catch(Exception ex){c.enabled=false;c.status="ERROR";c.lastError="Falha ao concluir autorização Google";return redirect(dest,"error");}}
    private RedirectView redirect(String path,String result){RedirectView v=new RedirectView(frontend+path+"?googleCalendar="+result);v.setExposeModelAttributes(false);return v;}
    public Map calendars(Owner o){Connection c=find(o);need(c!=null&&c.enabled,"Conecte uma conta Google primeiro");Map result=google(c).get().uri("https://www.googleapis.com/calendar/v3/users/me/calendarList?maxResults=250").retrieve().body(Map.class);return Map.of("calendars",result.getOrDefault("items",List.of()));}
    public Status select(Owner o,String id){Connection c=find(o);need(c!=null&&c.enabled,"Conecte uma conta Google primeiro");need(id!=null&&!id.isBlank()&&id.length()<500,"Calendário inválido");Map items=(Map)calendars(o);List<Map> list=(List<Map>)items.get("calendars");Map match=list.stream().filter(x->id.equals(x.get("id"))).findFirst().orElseThrow(()->new ResponseStatusException(HttpStatus.BAD_REQUEST,"Calendário não disponível para esta conta"));c.calendarId=id;c.calendarSummary=(String)match.get("summary");c.status="CONNECTED";em.createQuery("update GcEventSync s set s.status='QUEUED',s.calendarId=:cal,s.nextAttemptAt=:now where s.connectionId=:id and s.status in ('FAILED','SYNCED')").setParameter("cal",id).setParameter("now",Instant.now()).setParameter("id",c.id).executeUpdate();return view(o,c);}
    public void disconnect(Owner o){Connection c=find(o);if(c==null)return;c.enabled=false;c.accessEncrypted=null;c.refreshEncrypted=null;c.status="DISCONNECTED";c.lastError=null;em.createQuery("update GcEventSync s set s.status='DISCONNECTED' where s.connectionId=:id and s.status in ('QUEUED','FAILED')").setParameter("id",c.id).executeUpdate();}
    public Map<String,Object> retry(Owner o){Connection c=find(o);need(c!=null&&c.enabled,"Conecte uma conta Google primeiro");int n=em.createQuery("update GcEventSync s set s.status='QUEUED',s.nextAttemptAt=:now,s.lastError=null where s.connectionId=:id and s.status='FAILED'").setParameter("now",Instant.now()).setParameter("id",c.id).executeUpdate();return Map.of("queued",n);}
    public void enqueue(Appointment a,String operation){Connection c=em.createQuery("select c from GcConnection c where c.ownerType='TENANT' and c.ownerId=:t and c.enabled=true and c.calendarId is not null",Connection.class).setParameter("t",a.getTenantId()).getResultStream().findFirst().orElse(null);if(c==null)c=em.createQuery("select c from GcConnection c where c.ownerType='BARBER' and c.ownerId=:b and c.enabled=true and c.calendarId is not null",Connection.class).setParameter("b",a.getBarberId()).getResultStream().findFirst().orElse(null);if(c==null)return;final Connection chosen=c;EventSync s=em.createQuery("select s from GcEventSync s where s.tenantId=:t and s.appointmentId=:a",EventSync.class).setParameter("t",a.getTenantId()).setParameter("a",a.getId()).getResultStream().findFirst().orElseGet(()->{EventSync n=new EventSync();n.tenantId=a.getTenantId();n.appointmentId=a.getId();em.persist(n);return n;});if(s.eventId!=null&&s.connectionId!=null&&!s.connectionId.equals(chosen.id))s.previousConnectionId=s.connectionId;s.connectionId=chosen.id;s.calendarId=chosen.calendarId;s.operation=operation;s.status="QUEUED";s.nextAttemptAt=Instant.now();s.lastError=null;s.updatedAt=Instant.now();}
    private RestClient google(Connection c){if(c.accessExpiresAt==null||c.accessExpiresAt.isBefore(Instant.now().plusSeconds(60)))refresh(c);return http.mutate().defaultHeader("Authorization","Bearer "+crypto.decrypt(c.tenantId,c.accessEncrypted)).build();}
    private void refresh(Connection c){need(c.refreshEncrypted!=null,"A autorização expirou; reconecte a conta Google");Map token=http.post().uri("https://oauth2.googleapis.com/token").contentType(MediaType.APPLICATION_FORM_URLENCODED).body("client_id="+enc(clientId)+"&client_secret="+enc(secret)+"&refresh_token="+enc(crypto.decrypt(c.tenantId,c.refreshEncrypted))+"&grant_type=refresh_token").retrieve().body(Map.class);c.accessEncrypted=crypto.encrypt(c.tenantId,(String)token.get("access_token"));c.accessExpiresAt=Instant.now().plusSeconds(((Number)token.getOrDefault("expires_in",3600)).longValue());}
    public List<UUID> queuedIds(){return em.createQuery("select s.id from GcEventSync s where s.status='QUEUED' and s.nextAttemptAt<=:n order by s.updatedAt",UUID.class).setParameter("n",Instant.now()).setMaxResults(30).getResultList();}
    public void recoverStuck(){em.createQuery("update GcEventSync s set s.status='QUEUED',s.nextAttemptAt=:now where s.status='PROCESSING' and s.updatedAt<:stale").setParameter("now",Instant.now()).setParameter("stale",Instant.now().minus(Duration.ofMinutes(5))).executeUpdate();}
    public void process(UUID id){EventSync s=em.find(EventSync.class,id,LockModeType.PESSIMISTIC_WRITE);if(s==null||!"QUEUED".equals(s.status))return;Connection c=em.find(Connection.class,s.connectionId);if(c==null||!c.enabled){s.status="DISCONNECTED";return;}s.status="PROCESSING";s.updatedAt=Instant.now();try{RestClient g=google(c);String calendar=s.calendarId==null?c.calendarId:s.calendarId;String url="https://www.googleapis.com/calendar/v3/calendars/"+encPath(calendar)+"/events";String eventId="lineup"+s.appointmentId.toString().replace("-","");if(s.previousConnectionId!=null&&s.eventId!=null){Connection old=em.find(Connection.class,s.previousConnectionId);if(old==null||!old.enabled)throw new IllegalStateException("A conexão que criou o evento precisa ser reconectada para transferir o evento com segurança");deleteIfPresent(google(old),s.eventCalendarId==null?old.calendarId:s.eventCalendarId,s.eventId);s.previousConnectionId=null;s.eventId=null;s.eventCalendarId=null;}if("DELETE".equals(s.operation)){deleteIfPresent(g,s.eventCalendarId==null?calendar:s.eventCalendarId,s.eventId);s.status="SYNCED";}else{Appointment a=em.find(Appointment.class,s.appointmentId);if(a==null||a.getStatus()==AppointmentStatus.CANCELED){s.operation="DELETE";deleteIfPresent(g,s.eventCalendarId==null?calendar:s.eventCalendarId,s.eventId);s.status="SYNCED";}else{if(s.eventCalendarId!=null&&!s.eventCalendarId.equals(calendar))deleteIfPresent(g,s.eventCalendarId,s.eventId);Map event=new HashMap(event(a));event.put("id",eventId);try{g.post().uri(url).contentType(MediaType.APPLICATION_JSON).body(event).retrieve().toBodilessEntity();}catch(org.springframework.web.client.HttpClientErrorException.Conflict conflict){g.put().uri(url+"/"+eventId).contentType(MediaType.APPLICATION_JSON).body(event).retrieve().toBodilessEntity();}s.eventId=eventId;s.eventCalendarId=calendar;s.status="SYNCED";}}s.lastError=null;s.attempts=0;c.lastSyncAt=Instant.now();c.lastError=null;}catch(Exception ex){s.attempts++;s.status=s.attempts>=10?"FAILED":"QUEUED";s.nextAttemptAt=Instant.now().plusSeconds(Math.min(3600,30L*(1L<<Math.min(s.attempts,7))));s.lastError="Falha ao sincronizar com Google Calendar";c.lastError=s.lastError;c.status="ERROR";}s.updatedAt=Instant.now();}
    private void deleteIfPresent(RestClient g,String calendarId,String eventId){if(eventId==null)return;String url="https://www.googleapis.com/calendar/v3/calendars/"+encPath(calendarId)+"/events/"+eventId;try{g.delete().uri(url).retrieve().toBodilessEntity();}catch(org.springframework.web.client.HttpClientErrorException.NotFound ignored){}}
    private Map event(Appointment a){Customer customer=customers.findById(a.getCustomerId()).orElse(null);BarberProfile b=barbers.findById(a.getBarberId()).orElse(null);Unit u=units.findById(a.getUnitId()).orElse(null);ZoneId zone=ZoneId.of(u==null?"UTC":u.getTimeZone());String title=(customer==null?"Cliente":customer.getFullName())+" — "+a.getItems().stream().map(AppointmentItem::getName).reduce((x,y)->x+", "+y).orElse("Atendimento");String loc=u==null?"":String.join(", ",Arrays.asList(n(u.getStreet()),n(u.getNumber()),n(u.getCity()),n(u.getState())).stream().filter(x->!x.isBlank()).toList());String description="Cliente: "+(customer==null?"":customer.getFullName())+"\nServiços: "+a.getItems().stream().map(AppointmentItem::getName).reduce((x,y)->x+", "+y).orElse("")+"\nProfissional: "+(b==null?"":b.getDisplayName());return Map.of("summary",title,"location",loc,"description",description,"start",Map.of("dateTime",a.getStartAt().atZone(zone).toOffsetDateTime().toString(),"timeZone",zone.getId()),"end",Map.of("dateTime",a.getEndAt().atZone(zone).toOffsetDateTime().toString(),"timeZone",zone.getId()));}
    private String n(String s){return s==null?"":s;}private String enc(String s){return java.net.URLEncoder.encode(s,java.nio.charset.StandardCharsets.UTF_8);}private String encPath(String s){return enc(s).replace("+","%20");}
    private void need(boolean b,String m){if(!b)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,m);}
}
